    var SolRow = jQuery(identifier).attr("data-SolRow");
    var FolderUniQIDS = jQuery(identifier).attr("data-FolderUniQIDS");
    var FolderPrntQIDS = jQuery(identifier).attr("data-FolderPrntQIDS");
