function FlipDivisions(nextboxnumer, havedata) {
    if (nextboxnumer == 1) {
        if (havedata == 'yes') {
            jQuery("#folderlistboxsectiondiv1").show();
        } else {
            jQuery("#folderlistboxsectiondiv1").hide();
        }
        jQuery("#folderlistboxsectiondiv2").hide();
        jQuery("#folderlistboxsectiondiv3").hide();
        jQuery("#folderlistboxsectiondiv4").hide();
        jQuery("#folderlistboxsectiondiv5").hide();
        jQuery("#folderlistboxsectiondiv6").hide();
        jQuery("#folderlistboxsectiondiv7").hide();
    } else if (nextboxnumer == 2) {
        jQuery("#folderlistboxsectiondiv1").show();
        if (havedata == 'yes') {
            jQuery("#folderlistboxsectiondiv2").show();
        } else {
            jQuery("#folderlistboxsectiondiv2").hide();
        }
        jQuery("#folderlistboxsectiondiv3").hide();
        jQuery("#folderlistboxsectiondiv4").hide();
        jQuery("#folderlistboxsectiondiv5").hide();
        jQuery("#folderlistboxsectiondiv6").hide();
        jQuery("#folderlistboxsectiondiv7").hide();
    } else if (nextboxnumer == 3) {
        jQuery("#folderlistboxsectiondiv1").show();
        jQuery("#folderlistboxsectiondiv2").show();
        if (havedata == 'yes') {
            jQuery("#folderlistboxsectiondiv3").show();
        } else {
            jQuery("#folderlistboxsectiondiv3").hide();
        }
        jQuery("#folderlistboxsectiondiv4").hide();
        jQuery("#folderlistboxsectiondiv5").hide();
        jQuery("#folderlistboxsectiondiv6").hide();
        jQuery("#folderlistboxsectiondiv7").hide();
    } else if (nextboxnumer == 4) {
        jQuery("#folderlistboxsectiondiv1").show();
        jQuery("#folderlistboxsectiondiv2").show();
        jQuery("#folderlistboxsectiondiv3").show();
        if (havedata == 'yes') {
            jQuery("#folderlistboxsectiondiv4").show();
        } else {
            jQuery("#folderlistboxsectiondiv4").hide();
        }
        jQuery("#folderlistboxsectiondiv5").hide();
        jQuery("#folderlistboxsectiondiv6").hide();
        jQuery("#folderlistboxsectiondiv7").hide();
    } else if (nextboxnumer == 5) {
        jQuery("#folderlistboxsectiondiv1").show();
        jQuery("#folderlistboxsectiondiv2").show();
        jQuery("#folderlistboxsectiondiv3").show();
        jQuery("#folderlistboxsectiondiv4").show();
        if (havedata == 'yes') {
            jQuery("#folderlistboxsectiondiv5").show();
        } else {
            jQuery("#folderlistboxsectiondiv5").hide();
        }
        jQuery("#folderlistboxsectiondiv6").hide();
        jQuery("#folderlistboxsectiondiv7").hide();
    } else if (nextboxnumer == 6) {
        jQuery("#folderlistboxsectiondiv1").show();
        jQuery("#folderlistboxsectiondiv2").show();
        jQuery("#folderlistboxsectiondiv3").show();
        jQuery("#folderlistboxsectiondiv4").show();
        jQuery("#folderlistboxsectiondiv5").show();
        if (havedata == 'yes') {
            jQuery("#folderlistboxsectiondiv6").show();
        } else {
            jQuery("#folderlistboxsectiondiv6").hide();
        }
        jQuery("#folderlistboxsectiondiv7").hide();
    } else if (nextboxnumer == 7) {
        jQuery("#folderlistboxsectiondiv1").show();
        jQuery("#folderlistboxsectiondiv2").show();
        jQuery("#folderlistboxsectiondiv3").show();
        jQuery("#folderlistboxsectiondiv4").show();
        jQuery("#folderlistboxsectiondiv5").show();
        jQuery("#folderlistboxsectiondiv6").show();
        if (havedata == 'yes') {
            jQuery("#folderlistboxsectiondiv7").show();
        } else {
            jQuery("#folderlistboxsectiondiv7").hide();
        }
    }
}